SELECT tblCase.CaseID, Replace([Case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty],"__","_") AS FileNumber, [Last_Name] & ", " & [First_Name] AS Name, tblCase.Orig_Atty, tblCase.HandlingAtty_Case, qryTakeOff_advanced_AR.SumOfCharge AS SumOfAdvancedAR, qryTakeOff_uncleared_deposits.SumOfDebit AS SumOfUnclearedDeposits, qryTakeOff_trust_account.Balance, qryTakeOff_unchashed_checks.SumOfCredit AS SumOfUncashedChecks, qry_TimeKeeping_CaseID_totals.SumOfTotal, qry_TimeKeeping_CaseID_totals.IANumber, qry_TimeKeeping_CaseID_totals.Bill_ID, qryTakeOff_cost_hold.CostHold, qryTrustCostsExpendedTotals.SumOfCostBalance, qry_advanced_totals_SUM.SumOfCharge AS SumofPrepaid, qryAdvLegalFeesSum.SumOfCharge AS SumAdvLegal, qryEarnedAdvLegalSUM.SumOfCredit AS SumEarnedAdv, qryCostReimbSUM.SumOfCredit AS SumCostReimb
FROM ((((((((((tblCase LEFT JOIN qryTakeOff_advanced_AR ON tblCase.CaseID = qryTakeOff_advanced_AR.CaseID) LEFT JOIN qryTakeOff_trust_account ON tblCase.CaseID = qryTakeOff_trust_account.CaseID) LEFT JOIN qryTakeOff_unchashed_checks ON tblCase.CaseID = qryTakeOff_unchashed_checks.CaseID) LEFT JOIN qryTakeOff_uncleared_deposits ON tblCase.CaseID = qryTakeOff_uncleared_deposits.CaseID) LEFT JOIN qry_TimeKeeping_CaseID_totals ON tblCase.CaseID = qry_TimeKeeping_CaseID_totals.CaseID) INNER JOIN qryTakeOff_cost_hold ON tblCase.CaseID = qryTakeOff_cost_hold.CaseID) LEFT JOIN qryAdvLegalFeesSum ON tblCase.CaseID = qryAdvLegalFeesSum.CaseID) LEFT JOIN qry_advanced_totals_SUM ON tblCase.CaseID = qry_advanced_totals_SUM.CaseID) LEFT JOIN qryTrustCostsExpendedTotals ON tblCase.CaseID = qryTrustCostsExpendedTotals.CaseID) LEFT JOIN qryEarnedAdvLegalSUM ON tblCase.CaseID = qryEarnedAdvLegalSUM.CaseID) LEFT JOIN qryCostReimbSUM ON tblCase.CaseID = qryCostReimbSUM.CaseID
GROUP BY tblCase.CaseID, Replace([Case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty],"__","_"), [Last_Name] & ", " & [First_Name], tblCase.Orig_Atty, tblCase.HandlingAtty_Case, qryTakeOff_advanced_AR.SumOfCharge, qryTakeOff_uncleared_deposits.SumOfDebit, qryTakeOff_trust_account.Balance, qryTakeOff_unchashed_checks.SumOfCredit, qry_TimeKeeping_CaseID_totals.SumOfTotal, qry_TimeKeeping_CaseID_totals.IANumber, qry_TimeKeeping_CaseID_totals.Bill_ID, qryTakeOff_cost_hold.CostHold, qryTrustCostsExpendedTotals.SumOfCostBalance, qry_advanced_totals_SUM.SumOfCharge, qryAdvLegalFeesSum.SumOfCharge, qryEarnedAdvLegalSUM.SumOfCredit, qryCostReimbSUM.SumOfCredit
ORDER BY [Last_Name] & ", " & [First_Name];